48		rep := Report{StudentID: studentID}
49		if _, ok := s.studentByID[studentID]; !ok {
50			return rep
51		}
52		rep.Found = true
53	
54		// 汇总每项要求的通过修读（按结果提交先后）。
55		type seqEntry struct {
56			id  string
57			seq int
58		}
59		passOrder := map[string][]seqEntry{}
60		for _, e := range s.enrollments {
61			if e.StudentID != studentID || e.Result != Passed {
