1	// credit 是本地课程学分与免修的命令行程序。
2	//
3	// 用法：credit -f 记录文件 <子命令> [参数...]
4	//
5	// 学生与课程：
6	//
7	//	student <编号>                              登记学生（编号唯一）
8	//	course <编号> <名称...> <正整数学分>          登记课程（初始开放）
9	//	course-close <编号>                          停开课程
10	//	course-open <编号>                           恢复开放课程
11	//	list-courses                                列出全部课程及状态
12	//
13	// 课程要求（编号在学生名下唯一）：
14	//
15	//	req <学生> <要求编号> <课程编号>              为学生登记课程要求
16	//
17	// 修读（编号在学生名下唯一）：
18	//
19	//	enroll <学生> <要求编号> <学期> <修读编号>    选课登记
20	//	pass   <学生> <修读编号>                      提交“通过”
21	//	fail   <学生> <修读编号>                      提交“未通过”
22	//
23	// 免修（编号在学生名下唯一）：
24	//
25	//	waiver        <学生> <要求编号> <免修编号> <依据...>  提交免修申请
26	//	revoke-waiver <学生> <免修编号> [原因...]            撤销有效免修
27	//
28	// 核对与查询：
29	//
30	//	check <学生>                                 按学生核对学分
31	//	show  <学生>                                 查看学生的要求、修读与免修历史
32	//
33	// 记录文件不存在时从空记录开始；文件无法读取或内容损坏时立即报错，
34	// 不会把它当作空记录覆盖。
35	package main
36	
37	import (
38		"bytes"
39		"errors"
40		"flag"
41		"fmt"
42		"io"
43		"os"
44		"strconv"
45		"strings"
46	
47		"github.com/descikazuyq/credit-record/credit"
48	)
49	
50	// 退出码：0 成功；1 业务规则被拒绝；2 记录文件错误。
51	const (
52		exitOK       = 0
53		exitRejected = 1
54		exitFile     = 2
55	)
56	
57	func main() {
58		os.Exit(run(os.Args[1:], os.Stdout, os.Stderr))
59	}
60	
61	func run(args []string, stdout, stderr io.Writer) int {
62		fs := flag.NewFlagSet("credit", flag.ContinueOnError)
63		fs.SetOutput(stderr)
64		fs.Usage = func() {
65			fmt.Fprintln(stderr, "用法：credit -f 记录文件 <子命令> [参数...]")
66			fmt.Fprintln(stderr, "子命令：student course course-close course-open list-courses")
67			fmt.Fprintln(stderr, "        req enroll pass fail waiver revoke-waiver check show")
68			fmt.Fprintln(stderr, "详情见 credit -h")
69		}
70		file := fs.String("f", "", "记录文件路径（必需）")
71		if err := fs.Parse(args); err != nil {
72			return exitRejected
73		}
74		if strings.TrimSpace(*file) == "" {
75			fmt.Fprintln(stderr, "错误：必须用 -f 指定记录文件")
76			fs.Usage()
77			return exitRejected
78		}
79		rest := fs.Args()
80		if len(rest) == 0 {
81			fmt.Fprintln(stderr, "错误：缺少子命令")
82			fs.Usage()
83			return exitRejected
84		}
85	
86		store, existed, err := credit.Load(*file)
87		if err != nil {
88			fmt.Fprintf(stderr, "错误：%v\n", err)
89			return exitFile
90		}
91	
92		cmd, cmdArgs := rest[0], rest[1:]
93	
94		// 业务结果先写入缓冲区，只有本次变更真正落盘后才允许出现在标准输出：
95		// 保存失败时绝不能把尚未写入文件的登记、更新、提交、撤销说成已经完成。
96		// 只读命令、幂等重复等不产生变更的操作不会保存，其结果照常输出。
97		var biz bytes.Buffer
98		code, err := dispatch(store, cmd, cmdArgs, &biz)
99		if err != nil {
100			fmt.Fprintf(stderr, "错误：%v\n", err)
101		}
102	
103		// 只有真正发生变更才落盘：只读核对、纯幂等重复、被拒绝而未写入数据的
104		// 请求都不改动文件，也不会为一次查询凭空创建空文件。被拒绝的免修申请
105		// 已写入免修历史（store 标记为已变更），仍会保存。损坏文件在 Load 阶段
106		// 就已返回，绝不会走到这里覆盖原文件。
107		if store.Dirty() {
108			if saveErr := store.Save(*file); saveErr != nil {
109				// 保存没有完成：丢弃全部业务输出，只在标准错误点名保存失败与
110				// 目标记录文件，按文件错误退出码 2 结束，退出码优先级高于
111				// 业务拒绝（例如历史都没存上的被拒绝免修）。
112				fmt.Fprintf(stderr, "错误：保存记录文件 %s 失败：%v\n", *file, saveErr)
113				return exitFile
114			}
115			// 首次创建记录文件的说明放在业务结果之后；保存失败时不会出现，
116			// 也不会谎称已经创建。
117			fmt.Fprint(stdout, biz.String())
118			if !existed {
119				fmt.Fprintf(stdout, "（记录文件 %s 不存在，已从空记录开始并创建）\n", *file)
120			}
121			return code
122		}
123		fmt.Fprint(stdout, biz.String())
124		return code
125	}
126	
127	func dispatch(s *credit.Store, cmd string, args []string, out io.Writer) (int, error) {
128		switch cmd {
129		case "student":
130			return cmdStudent(s, args, out)
131		case "course":
132			return cmdCourse(s, args, out)
133		case "course-close", "course-open":
134			return cmdCourseToggle(s, cmd, args, out)
135		case "list-courses":
136			return cmdListCourses(s, out)
137		case "req":
138			return cmdReq(s, args, out)
139		case "enroll":
140			return cmdEnroll(s, args, out)
141		case "pass", "fail":
