1	package credit
2	
3	import (
4		"encoding/json"
5		"fmt"
6		"io"
7		"unicode/utf8"
8	)
9	
10	// duplicateFieldError 表示同一个 JSON 对象内出现了重复字段名。
11	type duplicateFieldError struct {
12		field string
13	}
14	
15	func (e *duplicateFieldError) Error() string {
16		return fmt.Sprintf("同一 JSON 对象内字段名 %q 重复出现，字段归属无法确定", e.field)
17	}
18	
19	// scanDuplicateKeys 扫描第一份完整 JSON 值的 token 流，在每个对象内检查
20	// 字段名唯一；第一份值之后的字节一律不读（调用方另行检查完整记录之后是否
21	// 还拼接了多余内容，那里的报错信息需要与本检查区分开）。
22	//
23	// 背景：encoding/json 直接解进结构体（或 map）时，同一对象内的重复键会被
24	// 后一个静默覆盖，读不出“曾经写过两个”，因此在正常结构体解码之前先单独
25	// 扫描一遍 token 流。
26	//
27	// 规则：
28	//   - 同一个 JSON 对象内字段名只能出现一次；重复字段是否相邻、两个值是否
29	//     相同都不影响判定，发现即返回 *duplicateFieldError（含字段名）。
30	//   - 比较以 JSON 解码后的文字为准：Token() 返回的键名已完成 Unicode
31	//     反转义，所以直接写出与 \uXXXX 转义形式的同名键仍算重复。
32	//   - 限制只针对同一对象：对象与数组可任意嵌套，数组各元素、不同课程或
33	//     不同学生等不同对象各自携带同名字段是正常结构，互不比较。
34	//   - 字符串“值”里出现字段名（依据、课程名称等）不是键，不参与检查。
35	func scanDuplicateKeys(r io.Reader) error {
36		type frame struct {
37			isObj bool
38			// expectKey 仅对对象有意义：true 表示下一个字符串 token 是键
39			// （或直接遇到 '}'）；false 表示正在等待该键所对应的值。
40			// 对象内 token 天然按键、值、键、值交替（逗号不产生 token），
41			// 借此区分字符串 token 是键还是普通字符串值。
42			expectKey bool
43			keys      map[string]struct{}
44		}
45		var stack []frame
46		depth := 0
47	
48		push := func(isObj bool) {
49			f := frame{isObj: isObj}
50			if isObj {
51				f.expectKey = true
52				f.keys = map[string]struct{}{}
53			}
54			stack = append(stack, f)
55		}
56		// valueEnded 通知栈顶对象：刚读完一个值（标量或嵌套结构的结束括号）。
57		valueEnded := func() {
58			if n := len(stack); n > 0 {
59				f := &stack[n-1]
60				if f.isObj && !f.expectKey {
61					f.expectKey = true
62				}
63			}
64		}
65	
66		dec := json.NewDecoder(r)
67		for {
68			tok, err := dec.Token()
69			if err == io.EOF {
70				// 空输入交由后续结构体解码报错（空文件在更前面已被拒绝）。
71				return nil
72			}
73			if err != nil {
74				return err
75			}
76			switch t := tok.(type) {
77			case json.Delim:
78				switch t {
79				case '{':
80					depth++
81					push(true)
82				case '[':
83					depth++
84					push(false)
85				case '}', ']':
86					depth--
87					stack = stack[:len(stack)-1]
88					if depth == 0 {
89						// 唯一的顶层值已完整读完，其后内容不在本检查范围。
90						return nil
91					}
92					// 刚结束的嵌套对象/数组本身就是外层键所对应的值。
93					valueEnded()
94				}
95			case string:
96				n := len(stack)
97				if n > 0 && stack[n-1].isObj && stack[n-1].expectKey {
98					// 对象键：Token() 已按解码后的文字返回。
99					if _, dup := stack[n-1].keys[t]; dup {
100						return &duplicateFieldError{field: t}
101					}
102					stack[n-1].keys[t] = struct{}{}
103					stack[n-1].expectKey = false
104					continue
105				}
106				valueEnded()
107				if depth == 0 {
108					return nil // 顶层标量值
109				}
110			default:
111				// number、bool、nil 等标量值。
112				valueEnded()
113				if depth == 0 {
114					return nil
115				}
116			}
117		}
118	}
119	
120	// scanStringUnicode 按原始字节扫描第一份完整 JSON 值里的全部字符串
121	// （字段名与字段值），验证每个字符串都能还原为合法 Unicode 文字：
122	//   - 字符串中直接写入的字节必须是合法 UTF-8；
123	//   - \uXXXX 转义中的高位代理项（U+D800–U+DBFF）必须紧跟一个低位代理项
124	//     （U+DC00–U+DFFF）转义；孤立的低位代理项同样非法。
