	rep2 := s.CheckStudent("s2")
	if !rep1.Overflow {
		t.Fatal("s1 应超限")
	}
	if rep2.Overflow || rep2.TotalCredits != 1 {
		t.Fatalf("s2 不应受 s1 影响，Overflow=%v Total=%d", rep2.Overflow, rep2.TotalCredits)
	}
}

